# a message box unless the test wants the same information on stdout
function pcbMsg([string]$Key, [string]$Detail) {
  $t = $pcbL[$Key] -f $Detail
  if ($env:PCB_GUI_LAUNCH_ECHO) { Write-Host ('PCB-GUI-MSG ' + $Key + ' ' + $Detail); return }
  try {
    Add-Type -AssemblyName System.Windows.Forms -ErrorAction Stop
    [void][System.Windows.Forms.MessageBox]::Show($t, $pcbL.Caption)
  } catch { Write-Host ('PCB-GUI-MSG ' + $Key + ' ' + $Detail) }
}
$pcbFile = 'pcbang-bfe81f07.ps1'
